static void z_t1538_destroy(z_t1538_t* p);
static void z_t1538_destroy(z_t1538_t* p) {
    if (!p) return;
    free(p->indices);
    free(p->entries);
    /* NO free(p) -- the struct is on the stack */
}

static z_t1538_t z_t1538_create(uint64_t _capacity);
